"""Readings laid out on a sensor grid."""
import numpy as np
from numpy.core.numeric import normalize_axis_tuple


def cell_count(shape):
    return int(np.product(shape))


def to_grid(values, rows):
    return np.reshape(values, newshape=(rows, -1))


def stack_days(*days):
    """One row per day."""
    return np.row_stack(days)


def totals(grid, axes):
    """Sums over ``axes`` (negative axes allowed, validated like numpy does)."""
    axes = normalize_axis_tuple(axes, np.ndim(grid))
    return np.sum(grid, axis=axes)

