"""Sensor readings: loading, cleaning and summaries built on numpy."""
import numpy as np

MISSING = np.NaN


def as_floats(readings):
    """Readings as a float array; None marks a missing value."""
    return np.asarray([MISSING if r is None else r for r in readings], dtype=np.float_)


def clean(readings, fill=0.0):
    arr = as_floats(readings)
    return np.where(np.isnan(arr), fill, arr)


def wrap(buffer):
    """View an existing sequence as an array, without a copy when one can be avoided."""
    return np.array(buffer, copy=False)


def selected(ids, wanted):
    """Mask of the ids that are in ``wanted``."""
    return np.in1d(ids, wanted)


def low_median(values):
    """The median, taking the lower of the two middle readings."""
    return float(np.percentile(values, 50, interpolation="lower"))


def spread(values):
    """Peak to peak range of the readings."""
    return float(np.asarray(values).ptp())


def energy(power, times):
    """Energy as the area under a power curve sampled at ``times``."""
    return float(np.trapz(power, times))

