import numpy as np

from app import readings


def test_clean_fills_missing():
    out = readings.clean([1.5, None, 3.0], fill=-1.0)
    assert out.dtype == np.float64
    assert out.tolist() == [1.5, -1.0, 3.0]


def test_wrap_keeps_values():
    assert readings.wrap([1, 2, 3]).tolist() == [1, 2, 3]


def test_selected():
    mask = readings.selected(np.array([10, 11, 12, 13]), [11, 13])
    assert mask.tolist() == [False, True, False, True]


def test_low_median():
    assert readings.low_median([4.0, 1.0, 3.0, 2.0]) == 2.0


def test_spread():
    assert readings.spread([3.0, 9.5, 4.0]) == 6.5


def test_energy():
    assert readings.energy([0.0, 2.0, 2.0], [0.0, 1.0, 3.0]) == 5.0

