def calibrated(raw, gain=1.1, offset=0.05):
    """A float32 sensor value through a linear calibration, rounded for display."""
    value = np.float32(raw) * gain + offset
    return np.round(value, 6)

def test_calibrated_close():
    # A tolerance test, as real suites write it: it does not look at the dtype.
    assert abs(readings.calibrated(0.3) - 0.38) < 1e-6
